package com.bank.tempcte.db;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

// Models a session: a persistent transactions table + a session-scoped temp table.
public class SessionDb {
    private static final Logger log = Logger.getLogger(SessionDb.class.getName());

    public record Txn(long id, String account, BigDecimal amount) {}
    private final List<Txn> transactions = new ArrayList<>();
    private List<Txn> tempHighValue;   // null until staged; "dropped" at session end

    public void seed(Txn... t) { transactions.addAll(List.of(t)); }

    // CREATE TEMPORARY TABLE ... AS SELECT — persists for the session.
    public void createTempHighValue(BigDecimal threshold) {
        tempHighValue = transactions.stream()
                .filter(x -> x.amount().compareTo(threshold) >= 0)
                .toList();
        log.info(() -> "CREATE TEMPORARY TABLE tmp_high_value (" + tempHighValue.size() + " rows staged)");
    }

    public List<Txn> tempTable() {
        if (tempHighValue == null) throw new IllegalStateException("temp table not created");
        return tempHighValue;
    }

    // A CTE is scoped to one call — computed, used, discarded. Nothing persists.
    public List<Txn> cteHighValue(BigDecimal threshold) {
        List<Txn> cte = transactions.stream()
                .filter(x -> x.amount().compareTo(threshold) >= 0).toList();
        log.info(() -> "WITH high_value AS (...) — inlined, scoped to this statement only");
        return cte;
    }

    public void endSession() { tempHighValue = null; log.info("session ended → temp table auto-dropped"); }
}
