package com.bank.tempcte.service;

import com.bank.tempcte.db.SessionDb;
import com.bank.tempcte.db.SessionDb.Txn;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

public class ReconciliationService {
    private static final Logger log = Logger.getLogger(ReconciliationService.class.getName());

    // Multi-step pipeline reusing ONE temp table across several statements.
    public void runPipeline(SessionDb db, BigDecimal high, BigDecimal veryHigh) {
        db.createTempHighValue(high);                             // stage once

        // Step 1: summary by account (reads temp table)
        Map<String, BigDecimal> byAccount = new HashMap<>();
        for (Txn t : db.tempTable()) byAccount.merge(t.account(), t.amount(), BigDecimal::add);
        log.info(() -> "Step 1 summary by account: " + byAccount);

        // Step 2: flagged-for-review (reuses the SAME temp table — no re-scan)
        List<Txn> flagged = db.tempTable().stream()
                .filter(t -> t.amount().compareTo(veryHigh) >= 0).toList();
        log.info(() -> "Step 2 flagged for review: " + flagged.size() + " txns");
    }

    // A one-off statement where a CTE is the lighter, correct choice.
    public long oneShotCount(SessionDb db, BigDecimal high) {
        long count = db.cteHighValue(high).size();
        log.info(() -> "One-shot CTE count: " + count);
        return count;
    }
}
