package com.bank.tempcte;

import com.bank.tempcte.db.SessionDb;
import com.bank.tempcte.db.SessionDb.Txn;
import com.bank.tempcte.service.ReconciliationService;
import java.math.BigDecimal;
import java.util.logging.*;

public class TempCteDemo {
    private static final Logger log = Logger.getLogger(TempCteDemo.class.getName());

    public static void main(String[] args) {
        setupLogger();
        SessionDb db = new SessionDb();
        db.seed(
            new Txn(1, "SAV2001", new BigDecimal("150000")),
            new Txn(2, "SAV2001", new BigDecimal("1200000")),
            new Txn(3, "CUR3001", new BigDecimal("50000")),
            new Txn(4, "CUR3001", new BigDecimal("300000")));

        ReconciliationService svc = new ReconciliationService();
        BigDecimal high = new BigDecimal("100000"), veryHigh = new BigDecimal("1000000");

        log.info("=== Temp table: staged once, reused across steps ===");
        svc.runPipeline(db, high, veryHigh);

        log.info("=== CTE: single-statement, inlined ===");
        svc.oneShotCount(db, high);

        db.endSession();   // temp table auto-dropped
    }

    private static void setupLogger() {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch); root.setLevel(Level.ALL);
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
